// Expansion Algorithm
// status: ready
// Proliferate X times. (To proliferate, choose any number of permanents and/or players, then give each another counter of each kind already there.)
#[allow(unused_imports)] use cantrip_api::*;
fn ability_0(g: &mut dyn Game, item: &StackItem) -> Result<(), Suspend> { let asker = &Asker::new(item.object, item.controller);
{ let player = { let q: &dyn Query = g; Some(asker.controller).expect("a reference that always names a player") }; let times = { let q: &dyn Query = g; (i64::from(item.x)).clamp(0, 255) as u32 }; for _ in 0..times { g.proliferate(player, asker.source)?; }; }
g.end_sentence();
 Ok(()) }

